"use client"

import { useState } from "react"

import { HomesMapFrame } from "@/components/tybow/homes-map-frame"
import type { MapHome } from "@/components/tybow/homes-map"
import { cn } from "@/lib/utils"

export type HomesExplorerProps = {
  id?: string
  eyebrow?: string
  title: string
  note?: string
  homes: MapHome[]
}

function isDesktop() {
  return window.matchMedia("(min-width: 1280px)").matches
}

export function HomesExplorer({
  id = "map",
  eyebrow,
  title,
  note,
  homes,
}: HomesExplorerProps) {
  const [activeSlug, setActiveSlug] = useState<string | undefined>()

  function onCardClick(home: MapHome) {
    if (isDesktop()) {
      setActiveSlug((current) => (current === home.slug ? undefined : home.slug))
      return
    }
    if (home.href) window.location.href = home.href
  }

  return (
    <section id={id} className="bg-muted">
      <div className="mx-auto w-full max-w-[1600px] px-[7vw] py-section">
        {eyebrow ? (
          <p className="text-[0.7rem] font-medium tracking-[0.26em] text-primary uppercase">
            {eyebrow}
          </p>
        ) : null}
        <h2 className="mt-3 max-w-[18ch] font-display text-[length:clamp(1.85rem,3.2vw,3rem)] font-light tracking-[0.055em] text-foreground uppercase">
          {title}
        </h2>

        <div className="mt-8 grid gap-4 xl:grid-cols-[minmax(0,1.2fr)_minmax(24rem,0.8fr)] xl:items-start">
          <div className="relative isolate z-0 min-h-[50svh] overflow-hidden outline outline-foreground/10 xl:col-start-2 xl:row-start-1 xl:sticky xl:top-8 xl:h-[calc(100dvh-6rem)] xl:min-h-[28rem]">
            <div className="absolute inset-0">
              <HomesMapFrame
                homes={homes}
                activeSlug={activeSlug}
                onSelect={setActiveSlug}
              />
            </div>
          </div>

          <ul className="relative z-10 grid grid-cols-2 gap-3 xl:col-start-1 xl:row-start-1">
            {homes.map((home) => {
              const active = home.slug === activeSlug
              const photo = home.photos[0]
              return (
                <li key={home.slug}>
                  <article
                    className={cn(
                      "group relative flex flex-col overflow-hidden bg-card outline transition-shadow",
                      active
                        ? "outline-primary shadow-[0_12px_32px_color-mix(in_oklch,var(--foreground)_12%,transparent)]"
                        : "outline-foreground/10 hover:shadow-[0_10px_28px_color-mix(in_oklch,var(--foreground)_8%,transparent)]",
                    )}
                  >
                    <button
                      type="button"
                      onClick={() => onCardClick(home)}
                      aria-pressed={active}
                      className="relative block aspect-[3/2] w-full overflow-hidden bg-muted"
                    >
                      {photo?.src ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img
                          src={photo.src}
                          alt={photo.alt}
                          className="absolute inset-0 size-full object-cover"
                        />
                      ) : null}
                    </button>
                    <button
                      type="button"
                      onClick={() => onCardClick(home)}
                      aria-pressed={active}
                      className="flex flex-col px-3 py-2.5 pr-12 text-left md:px-4 md:py-3"
                    >
                      <h3 className="font-display text-[15px] leading-tight text-foreground md:text-base">
                        {home.name}
                      </h3>
                      <p className="mt-0.5 text-[11px] text-muted-foreground md:text-xs">
                        {[home.community, home.city].filter(Boolean).join(" · ")}
                      </p>
                      {home.price ? (
                        <p className="mt-1 font-display text-[14px] text-foreground tabular-nums md:text-[15px]">
                          {home.price}
                        </p>
                      ) : null}
                    </button>
                    <a
                      href={home.href}
                      className="absolute right-2.5 bottom-2.5 z-10 text-[0.68rem] font-semibold tracking-[0.12em] text-primary uppercase"
                    >
                      View home
                    </a>
                  </article>
                </li>
              )
            })}
          </ul>
        </div>
        {note ? (
          <p className="mt-3 text-xs text-muted-foreground">{note}</p>
        ) : null}
      </div>
    </section>
  )
}

"use client"

import { useEffect, useState, type ComponentType } from "react"

import type { HomesMapProps } from "@/components/tybow/homes-map"

export function HomesMapFrame(props: HomesMapProps) {
  const [MapView, setMapView] = useState<ComponentType<HomesMapProps> | null>(
    null,
  )
  const [failed, setFailed] = useState(false)

  useEffect(() => {
    let on = true
    import("@/components/tybow/homes-map")
      .then((mod) => {
        if (on) setMapView(() => mod.HomesMap)
      })
      .catch(() => {
        if (on) setFailed(true)
      })
    return () => {
      on = false
    }
  }, [])

  if (failed) {
    return (
      <div className="flex h-full min-h-[22rem] items-center justify-center bg-muted px-6 text-center text-sm text-foreground">
        <p>Map didn’t load here.</p>
      </div>
    )
  }

  if (!MapView) {
    return (
      <div
        className="h-full min-h-[22rem] w-full bg-muted"
        aria-busy="true"
        aria-label="Map"
      />
    )
  }

  return <MapView {...props} />
}

"use client"

import { useEffect, useRef } from "react"
import {
  LngLatBounds,
  Map as MapLibreMap,
  Marker,
  NavigationControl,
  Popup,
  setWorkerUrl,
} from "maplibre-gl"
import "maplibre-gl/dist/maplibre-gl.css"

import "./tybow-map.css"

import { attachTileFallback, MAP_STYLE } from "@/components/tybow/map-style"

export type MapHome = {
  slug: string
  name: string
  href: string
  community?: string
  city?: string
  price?: string
  lat: number
  lng: number
  photos: { src?: string; alt: string }[]
}

export type HomesMapProps = {
  homes: readonly MapHome[]
  activeSlug?: string
  onSelect?: (slug: string | undefined) => void
}

if (typeof window !== "undefined") {
  try {
    setWorkerUrl("/maplibre/maplibre-gl-worker.mjs")
  } catch {
    /* Demo copies the worker into /public/maplibre. */
  }
}

const SALE_TAG = `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M17.5 5a1.5 1.5 0 1 1 0 3a1.5 1.5 0 0 1 0-3"/><path d="M2.774 11.144c-1.003 1.12-1.024 2.81-.104 4a34 34 0 0 0 6.186 6.186c1.19.92 2.88.899 4-.104a92 92 0 0 0 8.516-8.698a1.95 1.95 0 0 0 .47-1.094c.164-1.796.503-6.97-.902-8.374s-6.578-1.066-8.374-.901a1.95 1.95 0 0 0-1.094.47a92 92 0 0 0-8.698 8.515Z"/><path stroke-linecap="round" stroke-linejoin="round" d="M13.788 12.367c.022-.401.134-1.135-.476-1.693m0 0a2.3 2.3 0 0 0-.797-.451c-1.257-.443-2.8 1.039-1.708 2.396c.587.73 1.04.954.996 1.782c-.03.582-.602 1.191-1.356 1.423c-.655.202-1.378-.065-1.835-.576c-.559-.624-.502-1.212-.507-1.468m5.208-3.105L14 9.986m-5.34 5.34l-.653.653"/></g></svg>`

const CHEVRON_LEFT = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg>`
const CHEVRON_RIGHT = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg>`
const CLOSE_X = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 6 6 18M6 6l12 12"/></svg>`

function pinStyles(active: boolean) {
  return [
    "width:34px",
    "height:34px",
    "padding:0",
    "border-radius:999px",
    "border:2px solid var(--background)",
    "box-shadow:0 6px 16px color-mix(in oklch, var(--foreground) 28%, transparent)",
    "cursor:pointer",
    "display:flex",
    "align-items:center",
    "justify-content:center",
    "line-height:0",
    "color:var(--primary-foreground)",
    "overflow:hidden",
    "transition-property:background-color",
    "transition-duration:150ms",
    `background:${active ? "var(--primary)" : "var(--foreground)"}`,
  ].join(";")
}

function paintPin(el: HTMLElement, active: boolean) {
  el.style.background = active ? "var(--primary)" : "var(--foreground)"
}

function makePin(label: string, active: boolean) {
  const el = document.createElement("button")
  el.type = "button"
  el.setAttribute("aria-label", label)
  el.style.cssText = pinStyles(active)
  el.innerHTML = SALE_TAG
  return el
}

function esc(value: string) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll('"', "&quot;")
}

function directionsHref(home: MapHome) {
  return `https://www.google.com/maps/dir/?api=1&destination=${home.lat},${home.lng}`
}

function popupHtml(home: MapHome) {
  const photos = home.photos.filter((photo) => photo.src).slice(0, 8)
  const slides = photos
    .map(
      (photo, index) =>
        `<img src="${esc(photo.src ?? "")}" alt="${esc(home.name)}, photo ${index + 1}" draggable="false" />`,
    )
    .join("")
  const count = photos.length
  const note = [home.city, home.price].filter(Boolean).join(" · ")

  return `<div class="tybow-home-popup">
    <div class="tybow-home-popup-carousel" data-carousel data-total="${count}" data-listing="${esc(home.href)}">
      <button type="button" class="tybow-home-popup-close" data-close aria-label="Close">${CLOSE_X}</button>
      <a class="tybow-home-popup-photos" data-link href="${esc(home.href)}" aria-label="View ${esc(home.name)}">
        <div class="tybow-home-popup-track" data-track>${slides}</div>
      </a>
      ${
        count > 1
          ? `<button type="button" class="tybow-home-popup-nav tybow-home-popup-prev" data-prev aria-label="Previous photo">${CHEVRON_LEFT}</button>
      <button type="button" class="tybow-home-popup-nav tybow-home-popup-next" data-next aria-label="Next photo">${CHEVRON_RIGHT}</button>
      <p class="tybow-home-popup-count" data-count>1 / ${count}</p>`
          : ""
      }
    </div>
    <div class="tybow-home-popup-body">
      <p class="tybow-home-popup-cat">${esc(home.community ?? "")}</p>
      <p class="tybow-home-popup-name">${esc(home.name)}</p>
      ${note ? `<p class="tybow-home-popup-note">${esc(note)}</p>` : ""}
      <div class="tybow-home-popup-actions">
        <a class="tybow-home-popup-primary" href="${esc(home.href)}">See this home</a>
        <a class="tybow-home-popup-secondary" href="${esc(directionsHref(home))}" target="_blank" rel="noreferrer">Directions</a>
      </div>
    </div>
  </div>`
}

function bindPopup(root: HTMLElement, popup: Popup, onClose: () => void) {
  bindCarousel(root)
  const close = root.querySelector<HTMLButtonElement>("[data-close]")
  if (!close || close.dataset.bound === "true") return
  close.dataset.bound = "true"
  close.addEventListener("click", (event) => {
    event.preventDefault()
    event.stopPropagation()
    popup.remove()
    onClose()
  })
}

function bindCarousel(root: HTMLElement) {
  const carousel = root.querySelector<HTMLElement>("[data-carousel]")
  const track = carousel?.querySelector<HTMLElement>("[data-track]")
  const countEl = carousel?.querySelector<HTMLElement>("[data-count]")
  const prev = carousel?.querySelector<HTMLButtonElement>("[data-prev]")
  const next = carousel?.querySelector<HTMLButtonElement>("[data-next]")
  if (!carousel || !track || carousel.dataset.bound === "true") return
  carousel.dataset.bound = "true"

  const total = track.children.length
  let index = 0

  const go = (nextIndex: number) => {
    index = (nextIndex + total) % total
    track.style.transform = `translate3d(-${index * 100}%,0,0)`
    if (countEl) countEl.textContent = `${index + 1} / ${total}`
  }

  prev?.addEventListener("click", (event) => {
    event.preventDefault()
    event.stopPropagation()
    go(index - 1)
  })
  next?.addEventListener("click", (event) => {
    event.preventDefault()
    event.stopPropagation()
    go(index + 1)
  })
  carousel.addEventListener("pointerdown", (event) => event.stopPropagation())
}

function fitOverlayInView(map: MapLibreMap, marker: Marker, popup: Popup) {
  const mapEl = map.getContainer()
  const popupEl = popup.getElement()
  const pinEl = marker.getElement()
  if (!popupEl || !pinEl) return

  const mapRect = mapEl.getBoundingClientRect()
  const popupRect = popupEl.getBoundingClientRect()
  const pinRect = pinEl.getBoundingClientRect()
  const pad = { top: 14, right: 56, bottom: 36, left: 14 }
  const left = Math.min(popupRect.left, pinRect.left)
  const right = Math.max(popupRect.right, pinRect.right)
  const top = Math.min(popupRect.top, pinRect.top)
  const bottom = Math.max(popupRect.bottom, pinRect.bottom)
  const viewLeft = mapRect.left + pad.left
  const viewRight = mapRect.right - pad.right
  const viewTop = mapRect.top + pad.top
  const viewBottom = mapRect.bottom - pad.bottom
  const viewW = viewRight - viewLeft
  const viewH = viewBottom - viewTop
  let dx = (left + right) / 2 - (viewLeft + viewRight) / 2
  let dy = (top + bottom) / 2 - (viewTop + viewBottom) / 2
  if (bottom - top > viewH) dy = bottom - viewBottom
  if (right - left > viewW) dx = left - viewLeft
  if (Math.abs(dx) < 2 && Math.abs(dy) < 2) return
  map.panBy([dx, dy], { duration: 380 })
}

function afterPopupLayout(map: MapLibreMap, marker: Marker, popup: Popup) {
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      fitOverlayInView(map, marker, popup)
    })
  })
}

export function HomesMap({ homes, activeSlug, onSelect }: HomesMapProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const mapRef = useRef<MapLibreMap | null>(null)
  const markersRef = useRef<Map<string, Marker>>(new Map())
  const selectRef = useRef(onSelect)
  const activeSlugRef = useRef(activeSlug)

  useEffect(() => {
    selectRef.current = onSelect
  }, [onSelect])

  useEffect(() => {
    activeSlugRef.current = activeSlug
  }, [activeSlug])

  useEffect(() => {
    const el = rootRef.current
    if (!el || mapRef.current) return

    const map = new MapLibreMap({
      container: el,
      style: MAP_STYLE,
      attributionControl: { compact: true },
      cooperativeGestures: true,
      fadeDuration: 0,
    })
    attachTileFallback(map)
    map.addControl(new NavigationControl({ showCompass: false }), "top-right")

    const bounds = new LngLatBounds()

    for (const home of homes) {
      const pin = makePin(home.name, home.slug === activeSlug)
      pin.addEventListener("click", (event) => {
        event.stopImmediatePropagation()
        if (activeSlugRef.current === home.slug) {
          selectRef.current?.(undefined)
          return
        }
        selectRef.current?.(home.slug)
      })
      const popup = new Popup({
        offset: 22,
        maxWidth: "min(280px, 86vw)",
        closeButton: false,
        closeOnClick: false,
        anchor: "bottom",
        className: "tybow-home-popup-shell",
      }).setHTML(popupHtml(home))

      const marker = new Marker({ element: pin })
        .setLngLat([home.lng, home.lat])
        .setPopup(popup)
        .addTo(map)

      popup.on("open", () => {
        const popupEl = popup.getElement()
        if (popupEl) {
          bindPopup(popupEl, popup, () => selectRef.current?.(undefined))
        }
        const currentMap = mapRef.current
        if (currentMap) afterPopupLayout(currentMap, marker, popup)
      })
      markersRef.current.set(home.slug, marker)
      bounds.extend([home.lng, home.lat])
    }

    const fit = () => {
      map.resize()
      if (bounds.isEmpty()) {
        map.setCenter([-80.25, 43.55])
        map.setZoom(13)
        return
      }
      map.fitBounds(bounds, { padding: 56, maxZoom: 14, duration: 0 })
    }

    map.once("load", fit)
    window.setTimeout(fit, 120)
    window.setTimeout(fit, 600)

    const ro = new ResizeObserver(() => map.resize())
    ro.observe(el)
    mapRef.current = map
    const markers = markersRef.current

    return () => {
      ro.disconnect()
      map.remove()
      mapRef.current = null
      markers.clear()
    }
    // Mount once; selection updates happen in the effect below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map) return

    markersRef.current.forEach((marker, slug) => {
      paintPin(marker.getElement(), slug === activeSlug)
      const popup = marker.getPopup()
      if (popup?.isOpen() && slug !== activeSlug) popup.remove()
    })

    if (!activeSlug) return
    const home = homes.find((item) => item.slug === activeSlug)
    const marker = markersRef.current.get(activeSlug)
    if (!home || !marker) return
    const popup = marker.getPopup()
    if (!popup) return
    if (!popup.isOpen()) {
      marker.togglePopup()
      return
    }
    afterPopupLayout(map, marker, popup)
  }, [activeSlug, homes])

  return (
    <div
      ref={rootRef}
      className="tybow-homes-map h-full w-full"
      role="region"
      aria-label="Map"
    />
  )
}

import type { Map as MapLibreMap, StyleSpecification } from "maplibre-gl"

type MapStyle = string | StyleSpecification

function rasterStyle(
  name: string,
  tiles: string[],
  attribution: string,
): StyleSpecification {
  return {
    version: 8,
    name,
    sources: {
      base: {
        type: "raster",
        tiles,
        tileSize: 256,
        attribution,
        maxzoom: 19,
      },
    },
    layers: [{ id: "base", type: "raster", source: "base" }],
  }
}

export const OPENFREEMAP_POSITRON =
  "https://tiles.openfreemap.org/styles/positron"

export const OSM_MONO_STYLE = rasterStyle(
  "osm-mono",
  ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
  "© OpenStreetMap contributors",
)

const TILE_STYLES: MapStyle[] = [OPENFREEMAP_POSITRON, OSM_MONO_STYLE]

export const MAP_STYLE = TILE_STYLES[0]

export function attachTileFallback(map: MapLibreMap) {
  let index = 0
  let switching = false
  map.on("error", () => {
    if (switching || index >= TILE_STYLES.length - 1) return
    switching = true
    index += 1
    map.setStyle(TILE_STYLES[index])
    map.once("idle", () => {
      switching = false
    })
  })
}

/* Trevalli homes-map: pins + popup cards. Token-only. */

.tybow-homes-map {
  container-type: size;
}

.tybow-homes-map .maplibregl-map {
  font-family: var(--font-sans);
  background: var(--muted);
}

.tybow-homes-map .maplibregl-canvas {
  filter: grayscale(1) contrast(0.92) brightness(1.06);
}

.tybow-homes-map button svg {
  display: block;
  pointer-events: none;
}

.tybow-home-popup-shell .maplibregl-popup-content {
  min-width: 16rem;
  overflow: hidden;
  padding: 0;
  color: var(--foreground);
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: 0 10px 28px color-mix(in oklch, var(--foreground) 14%, transparent);
}

.tybow-home-popup-carousel {
  position: relative;
  overflow: hidden;
  aspect-ratio: 5 / 4;
  background: var(--muted);
}

.tybow-home-popup-photos {
  display: block;
  height: 100%;
  margin: 0 !important;
  color: inherit;
  text-decoration: none !important;
}

.tybow-home-popup-track {
  display: flex;
  height: 100%;
  transition: transform 320ms cubic-bezier(0.2, 0, 0, 1);
}

.tybow-home-popup-track img {
  flex: 0 0 100%;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
}

.tybow-home-popup-nav,
.tybow-home-popup-close {
  position: absolute;
  z-index: 2;
  display: flex;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: color-mix(in oklch, var(--background) 92%, transparent);
  color: var(--foreground);
  box-shadow: 0 6px 16px color-mix(in oklch, var(--foreground) 16%, transparent);
  cursor: pointer;
}

.tybow-home-popup-nav {
  top: 50%;
  transform: translateY(-50%);
}

.tybow-home-popup-nav:active {
  transform: translateY(-50%) scale(0.96);
}

.tybow-home-popup-close {
  top: 8px;
  right: 8px;
  z-index: 4;
}

.tybow-home-popup-close:active {
  transform: scale(0.96);
}

.tybow-home-popup-prev {
  left: 8px;
}

.tybow-home-popup-next {
  right: 8px;
}

.tybow-home-popup-count {
  position: absolute;
  right: 10px;
  bottom: 8px;
  z-index: 2;
  margin: 0;
  padding: 5px 8px;
  border-radius: 999px;
  background: color-mix(in oklch, var(--foreground) 72%, transparent);
  color: var(--background);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.tybow-home-popup-body {
  padding: 12px 14px 14px;
}

.tybow-home-popup-cat {
  margin: 0;
  font-size: 12px;
  font-weight: 600;
  color: var(--primary);
}

.tybow-home-popup-name {
  margin: 4px 0 0;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 500;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.tybow-home-popup-note {
  margin: 6px 0 0;
  font-size: 13px;
  line-height: 1.4;
  color: var(--muted-foreground);
}

.tybow-home-popup-actions {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 12px;
}

.tybow-home-popup-primary {
  display: inline-flex;
  height: 36px;
  align-items: center;
  padding: 0 14px;
  background: var(--foreground);
  color: var(--background) !important;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none !important;
}

.tybow-home-popup-primary:active {
  transform: scale(0.96);
}

.tybow-home-popup-secondary {
